const extra = [];
for (let index = 0; index < 7; index++)
  for (const type of Object.keys(groups)) {
    const row = groups[type][index];
    if (!row) continue;
    let id,
      title,
      description,
      category,
      city,
      person,
      mode,
      condition,
      image,
      illustration;
    if (type === "object") {
      [
        id,
        title,
        description,
        category,
        city,
        person,
        illustration,
        condition,
      ] = row;
      mode = "Presencial";
    } else if (type === "service") {
      [id, title, description, category, city, person, mode, condition, image] =
        row;
    } else if (type === "need") {
      [
        id,
        title,
        description,
        category,
        city,
        person,
        mode,
        condition,
        illustration,
      ] = row;
    } else {
      [id, title, description, category, city, person, condition, image] = row;
      mode = "Presencial";
    }
    extra.push({
      id,
      type,
      title,
      description,
      category,
      city,
      person,
      mode,
      condition,
      image: image || "",
      illustration: illustration || "",
      imageAlt: image ? "Imagen ilustrativa de " + category.toLowerCase() : "",
      initials: person
        .split(/\s+/)
        .slice(0, 2)
        .map((x) => x[0])
        .join("")
        .toUpperCase(),
      date: 13 + extra.length,
      demo: true,
    });
  }
export const extraOpportunities = extra;
